sketches.source:
setcpm(60/4)

// Cello and drone alone, the prelude twice (an octave up the second time), then a held C
song("intro@4 prelude@16 prelude'@16 coda@4", "once")
// Steady, then a ritardando over the last four bars
tempomap("0:15 36:15 40:11")

// A prelude of broken chords, the same in both ears: C, Am, Dm7, G7
prelude: note("<[c3 e3 g3 c4 e4 g3 c4 e4] [a2 e3 a3 c4 e4 a3 c4 e4] [d3 f3 a3 c4 f4 a3 c4 f4] [g2 d3 g3 b3 f4 g3 b3 f4]>")
  .s("triangle").timbre("soft").attack(.005).decay(1.2).sustain(.08).release(1.4)
  .lpf(2200).room(.5).size(.8).gain(.26)
  .sections("prelude").variant(x => x.add(12).gain(.2))

// A cello holds each root, centred
cello: note("<c2 a1 d2 g1>").s("sawtooth").vib(4.5).vibdepth(.08).lpf(600)
  .attack(.6).sustain(.7).release(1.2).room(.5).gain(.16)
  .exceptSections("coda")

// The last chord, left to ring
final: note("[c2,g2,e3,c4,e4]").slow(4).s("triangle").timbre("soft")
  .attack(.01).decay(3).sustain(.15).release(4).room(.6).size(.8).gain(.22)
  .sections("coda")

// A 10 Hz binaural beat in the alpha range: each ear is detuned by 5 Hz. Keep it quiet,
// and quieter still in the intro and coda
drone: note("[c3,g3]").slow(4).s("sine").binaural(10)
  .attack(3).sustain(1).release(4).gain(bysec("intro:.07 coda:.06 *:.1"))

setcpm(72/4)

// Viola and cello alone, the theme twice, the viola's episode, the theme again and a final F
song("intro@4 theme@8 theme'@8 episode@8 theme@8 coda@2", "once")
// Steady, then a ritardando into the last chord
tempomap("0:18 34:18 38:12")

// One bowed string, named once; the brightness has a default
const bowed = (x, bright = 2400) => x.s("sawtooth").vib(5).vibdepth(.1)
  .attack(.08).sustain(.7).release(.4).lpf(bright)

// The tune: F, Dm, Bb, C7
const tune = note("<[a4@3 g4 f4@2 a4@2] [d5@4 c5@2 a4@2] [bb4@3 a4 g4@2 f4 d4] [e4@2 g4@2 c5@4]>")

// The players sit in a semicircle in front of you: 0 is straight ahead, negative is left
violin1: tune.bowed(3000).azimuth(-50).distance(2.5).room(.4).gain(.2)
  .sections("theme").variant(x => x.add(12).gain(.15))
violin2: note("<[c4 f4] [f4 a4] [d4 f4] [e4 g4]>")
  .bowed().azimuth(-18).distance(2.5).room(.4).gain(.15)
  .exceptSections("intro coda")
viola: note("<a3 a3 bb3 bb3>")
  .bowed(1800).azimuth(18).distance(2.5).room(.4).gain(.14)
  .sections("intro theme")
cello: note("<[f2 c3] [d2 a2] [bb1 f2] [c2 g2]>")
  .bowed(900).azimuth(50).distance(2.5).room(.4).gain(.22)
  .exceptSections("coda")

// In the episode the viola sings the tune an octave down, from its seat right of centre
solo: tune.add(-12).bowed(1800).azimuth(18).distance(2.5).room(.4).gain(.18)
  .sections("episode")

// The last F chord, held from both sides of the stage
highend: note("[a4,c5,f5]").slow(2).bowed(2400).attack(.4).release(3)
  .azimuth(-34).distance(2.5).room(.5).gain(.13).sections("coda")
lowend: note("[f2,c3,a3]").slow(2).bowed(1200).attack(.4).release(3)
  .azimuth(34).distance(2.5).room(.5).gain(.16).sections("coda")

setcpm(54/3)

// One cycle is a bar of 3/4; the long second beat is the sarabande's lean
// The pad alone, the sarabande with its repeat, a double, the sarabande again and a last chord
song("intro@2 (sarabande@8)*2 sarabande'@8 sarabande@8 coda@2", "once")
// Steady, then a ritardando into the last chord
tempomap("0:18 32:18 36:12")

// Dm, Bb, Gm, A, Dm, Bb, A7, Dm
const harpsichord = (x) => x.s("square").pw(.15)
  .attack(.002).decay(.4).sustain(0).release(.2).lpf(3200).room(.4)

// In the double (the primed pass) every note is struck twice
right: note("<[a4 d5@2] [f5 d5@2] [bb4 g4@2] [c#5@3] [e5 f5@2] [d5 bb4@2] [g4 e4@2] [d4@3]>")
  .harpsichord().gain(.18).sections("sarabande").variant(x => x.ply(2))
left: note("<d3 bb2 g2 a2 d3 bb2 a2 d2>").harpsichord().gain(.16)
  .sections("sarabande")

// The strings step through the interaural phase, two bars at a time
// 0 degrees: centred. 90: looser. 180: diffuse and all around, and nearly gone in mono
pad: note("<[d3,f3,a3] [bb2,d3,f3] [g2,bb2,d3] [a2,c#3,e3] [d3,f3,a3] [bb2,d3,f3] [a2,c#3,g3] [d3,f3,a3]>")
  .s("sawtooth").unison(2).detune(.1).iphase("<0 0 90 90 180 180 90 90>")
  .lpf(1000).attack(1).sustain(1).release(2).gain(.1)
  .exceptSections("coda")

// The last chord: the harpsichord rings and the pad returns to a point, in phase
final: note("[d2,a2,d3,f3,a3,d4]").harpsichord().decay(2.5).release(2).gain(.14)
  .sections("coda")
codapad: note("[d3,f3,a3]").slow(2).s("sawtooth").unison(2).detune(.1).iphase(0)
  .lpf(1000).attack(.5).sustain(1).release(3).gain(.1).sections("coda")

setcpm(60/3)

// One cycle is a bar of 3/4
// Drone and bass alone, the minuet with its repeat, an octave lower, once more, a last chord
song("intro@4 minuet@16 minuet'@8 minuet@8 coda@4", "once")
// Steady, then a ritardando over the last four bars
tempomap("0:20 36:20 40:13")

// A 2 Hz binaural drone on an open fifth: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("[bb1,f2]").slow(8).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.22)

// The harp minuet, floating a little above your head: Bb, Bb, Cm, F, Bb, Eb, F, Bb
harp: note("<[d5 c5 bb4] [f4@2 bb4] [c5 eb5 d5] [c5@3] [d5 f5 eb5] [d5@2 bb4] [c5 a4 c5] [bb4@3]>")
  .s("triangle").timbre("soft").attack(.002).decay(1.4).sustain(0).release(1.4)
  .elevation(30).distance(2).room(.6).size(.85).gain(.22)
  .sections("minuet").variant(x => x.add(-12))

// A soft root on each downbeat
bass: note("<bb1 bb1 c2 f1 bb1 eb2 f1 bb1>").s("triangle").timbre("soft")
  .attack(.01).decay(1).sustain(0).release(1).gain(.18)
  .exceptSections("coda")

// The last chord, still floating above your head
final: note("[bb3,d4,f4,bb4]").slow(4).s("triangle").timbre("soft")
  .attack(.002).decay(4).sustain(0).release(4)
  .elevation(30).distance(2).room(.6).size(.85).gain(.2)
  .sections("coda")

// Crickets far away
crickets: s("insect").slow(4).distance(8).gain(.05)
